MultiLanguageItemData['de'][9192] = {name = "Zauberfoliant der Verderbnis", additional_info = "Klassen: Hexenmeister , Mönch\nBenötigt Stufe 4\n[q2]Benutzen: Lehrt 'Verderbnis' (Rang 1).\n[q2]Verderbt das Ziel und verursacht so im Verlauf von 18 Sek. insgesamt 40 Schattenschaden.\nVerkaufspreis:"}
