MultiLanguageItemData['de'][9194] = {name = "Zauberfoliant des Fluchs der Pein", additional_info = "Klassen: Hexenmeister , Mönch\nBenötigt Stufe 8\n[q2]Benutzen: Lehrt 'Fluch der Pein' (Rang 1).\n[q2]Fügt dem Ziel immer stärkere Schmerzen zu, die im Verlauf von 24 Sek. bis zu ( 10 * 10) Schattenschaden verursachen.\n\n Zunächst wird nur geringer Schaden verursacht, der aber mit jedem Tick zunimmt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][9195] = {name = "Zauberfoliant des Seelenabziehens", additional_info = "Klassen: Hexenmeister , Mönch\nBenötigt Stufe 10\n[q2]Benutzen: Lehrt 'Furcht' (Rang 1).\n[q2]Verängstigt den Gegner, woraufhin er bis zu 20 Sek. lang [ Glyphe 'Furcht' : vor Furcht erstarrt / voller Furcht flüchtet].\n\nFurchtbeschränkung\nAuf ein Ziel beschränkt. Verursachter Schaden kann den Furchteffekt entfernen. [ Seelenbrand: Furcht : Seelenbrand:\nEuer Zauber 'Furcht' wird zu einem Spontanzauber, der ein Ziel 3 Sek. lang mit Entsetzen erfüllt. ]\nVerkaufspreis:"}
MultiLanguageItemData['de'][9197] = {name = "Elixier der Traumvision", additional_info = "Benötigt Stufe 38\n[q2]Benutzen: Gewährt Euch eine Traumvision, mit der Ihr Gegenden erforschen könnt, die zu gefährlich sind, sie persönlich zu erforschen. (3 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][9198] = {name = "Zauberfoliant der Lebenslinie", additional_info = "Klassen: Hexenmeister , Mönch\nBenötigt Stufe 12\n[q2]Benutzen: Lehrt 'Lebenslinie' (Rang 1).\n[q2]Opfert 2 % Eurer gesamten Gesundheit, um Euren beschworenen Dämon alle 1 Sek. um 6 % seiner gesamten Gesundheit zu heilen. Hält 6 Sek. lang an.\n [\nMachterfüllte Kanalisierung\nWenn dieser Zauber erneut gewirkt wird, bevor seine Effektdauer endet, wird die Effektdauer um 0.05 Sek. erhöht.\n Bis zu 0-mal stapelbar. ] [ Seelenbrand: Lebenslinie : Seelenbrand:\nRegeneriert 140% mehr Gesundheit und verringert den erlittenen Schaden 10 Sek. lang um 30 %. ]\nVerkaufspreis:"}
MultiLanguageItemData['de'][9199] = {name = "Zauberfoliant des Fluchs der Tollkühnheit", additional_info = "Klassen: Hexenmeister , Mönch\nBenötigt Stufe 12\n[q2]Benutzen: Lehrt 'Lebenslinie' (Rang 1).\n[q2]Opfert 2 % Eurer gesamten Gesundheit, um Euren beschworenen Dämon alle 1 Sek. um 6 % seiner gesamten Gesundheit zu heilen. Hält 6 Sek. lang an.\n [\nMachterfüllte Kanalisierung\nWenn dieser Zauber erneut gewirkt wird, bevor seine Effektdauer endet, wird die Effektdauer um 0.05 Sek. erhöht.\n Bis zu 0-mal stapelbar. ] [ Seelenbrand: Lebenslinie : Seelenbrand:\nRegeneriert 140% mehr Gesundheit und verringert den erlittenen Schaden 10 Sek. lang um 30 %. ]\nVerkaufspreis:"}
MultiLanguageItemData['de'][9200] = {name = "Zauberfoliant des Fluchs der Schwäche II", additional_info = "Klassen: Hexenmeister , Mönch\nBenötigt Stufe 14\n[q2]Benutzen: Lehrt 'Blutsauger' (Rang 1).\n[q2]Entzieht dem Ziel Leben, wodurch es alle 1 Sek. ( 13 + 0.334 * Spell power) Schattenschaden erleidet und der Zaubernde 2 % seiner gesamten Gesundheit regeneriert. Hält 6 Sek. lang an. [ Seelenbrand : Seelenbrand:\nErhöht den Heilungseffekt um ( 3 / 2 * 100 - 100)%. ]\nVerkaufspreis:"}
