MultiLanguageItemData['de'][16049] = {name = "[q2]Bauplan: Dunkeleisenbombe", additional_info = "Benötigt Ingenieurskunst (285)\n[q2]Benutzen: Lehrt Euch die Herstellung einer Dunkeleisenbombe.\nVerkaufspreis:\nDunkeleisenbombe\nBenötigt Ingenieurskunst (285)\n[q2]Benutzen: Fügt Zielen in einem Umkreis von 5 Metern 126 Feuerschaden zu und macht sie 4 Sek. lang handlungsunfähig. Jeglicher Schaden wird den Effekt abbrechen. Unzuverlässig gegen Ziele über Stufe 73. (1 Min Abklingzeit)\nVerkaufspreis: \nBenötigt Thoriumapparat (2), Dunkeleisenbarren , Dichtes Sprengpulver (3), Runenstoff (3)"}
MultiLanguageItemData['de'][16050] = {name = "Bauplan: Empfindlicher Arkanitwandler", additional_info = "Benötigt Ingenieurskunst (285)\n[q2]Benutzen: Lehrt Euch die Herstellung eines empfindlichen Arkanitwandlers.\nVerkaufspreis:\nEmpfindlicher Arkanitwandler\nVerkaufspreis:\nBenötigt Arkanitbarren , Eisenweberseide"}
