MultiLanguageItemData['de'][16052] = {name = "[q2]Bauplan: Modularer Stimmenverstärker", additional_info = "Benötigt Ingenieurskunst (290)\n[q2]Benutzen: Lehrt Euch die Herstellung eines modularen Stimmenverstärkers.\nVerkaufspreis:\n[q2]Modularer Stimmenverstärker\nWird beim Anlegen gebunden\nHals\n[q2]Anlegen: Verringert die Wirkungsdauer jeglicher Stille- und Unterbrechungseffekte gegen den Träger um 10%. Dieser Effekt ist nicht mit anderen Effekten dieser Art stapelbar.\nVerkaufspreis: \nBenötigt Empfindlicher Arkanitwandler (2), Goldkraftkern , Thoriumapparat , Großer Opal"}
MultiLanguageItemData['de'][16053] = {name = "[q2]Bauplan: Schutzbrille des Meisteringenieurs", additional_info = "Benötigt Ingenieurskunst (290)\n[q2]Benutzen: Lehrt Euch die Herstellung einer Schutzbrille des Meisteringenieurs.\nVerkaufspreis:\n[q2]Schutzbrille des Meisteringenieurs\nWird beim Anlegen gebunden\n{Kopf} {Stoff}\n118 Rüstung\n+16 Ausdauer\n+17 Willenskraft\nHaltbarkeit 70 / 70\nBenötigt Ingenieurskunst (280)\nVerkaufspreis: \nBenötigt Feuerschutzbrille , Gewaltiger Smaragd (2), Verzaubertes Leder (4)"}
MultiLanguageItemData['de'][16054] = {name = "[q2]Bauplan: Arkanitdrachling", additional_info = "Benötigt Ingenieurskunst (300)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Arkanitdrachlings.\nVerkaufspreis:\n[q3]Arkanitdrachling\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 50\nBenötigt Ingenieurskunst (300)\n[q2]Benutzen: Aktiviert Euren Arkanitdrachling, damit er 1 Min. lang für Euch kämpft. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Mechanischer Mithrildrachling , Empfindlicher Arkanitwandler (4)"}
MultiLanguageItemData['de'][16055] = {name = "[q2]Bauplan: Arkane Bombe", additional_info = "Benötigt Ingenieurskunst (300)\n[q2]Benutzen: Lehrt Euch die Herstellung einer arkanen Bombe.\nVerkaufspreis:\nArkane Bombe\nBenötigt Ingenieurskunst (300)\n[q2]Benutzen: Entzieht Zielen im Explosionsradius 901 Mana und fügt ihnen Schaden in Höhe von 50% des abgezogenen Manas zu. Bringt die Ziele im Effektbereich außerdem 5 Sek. lang zum Schweigen.\n\n Versagenschance erhöht, wenn Ihr über Stufe 60 seid. (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Empfindlicher Arkanitwandler , Thoriumbarren (3), Runenstoff"}
