MultiLanguageItemData['de'][18650] = {name = "Bauplan: EZ-Thro-Dynamit II", additional_info = "Benötigt Ingenieurskunst (200)\n[q2]Benutzen: Lehrt Euch die Herstellung von EZ-Thro-Dynamit II.\nVerkaufspreis: \nEZ-Thro-Dynamit II\nBenötigt Stufe 30\n[q2]Benutzen: Fügt 250 Feuerschaden in einem Radius von 5 Metern zu (sollte es das Ziel treffen; es gelten Beschränkungen). (1 Min Abklingzeit)\n[q]\"Das Dynamit für jedermann, das selten* in der Hand hochgeht, mit mehr als der doppelten Sprengkraft von einfachem EZ-Thro.\"\nVerkaufspreis:\nBenötigt Robustes Sprengpulver , Magiestoff (2)"}
MultiLanguageItemData['de'][18651] = {name = "Bauplan: Echtsilberumwandler", additional_info = "Benötigt Ingenieurskunst (260)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Echtsilberumwandlers.\nVerkaufspreis:\nEchtsilberumwandler\nVerkaufspreis:\nBenötigt Echtsilberbarren (2), Elementarerde (2), Elementarluft"}
