MultiLanguageItemData['de'][21217] = {name = "Weisenfisch Supreme", additional_info = "Benötigt Stufe 30\n[q2]Benutzen: Stellt im Verlauf von 21 Sek. 292320 Gesundheit und 438134 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und regeneriert 15 Min. lang alle 5 Sekunden 8 Mana.\nVerkaufspreis:"}
MultiLanguageItemData['de'][21218] = {name = "[q3]Blauer Qirajiresonanzkristall", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 40\nBenötigtUnerfahrener Reiter\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier kann nur im Tempel von Ahn'Qiraj beschworen werden.\n[q2]Stößt ein Hochfrequenzsignal aus, das eine Qirajipanzerdrohne dazu zwingt, sich aus dem Boden unter dem Tempel von Ahn'Qiraj an die Oberfläche zu graben. Der Silithide gehorcht seinem Beschwörer und kann innerhalb des Tempels von Ahn'Qiraj als Reittier benutzt werden. Jegliche feindseligen Handlungen gegen den Reiter zwingen die Qirajipanzerdrohne, sich wieder einzugraben."}
MultiLanguageItemData['de'][21219] = {name = "Rezept: Weisenfisch Supreme", additional_info = "Benötigt Kochkunst (175)\n[q2]Benutzen: Lehrt Euch, wie man Weisenfisch Surpreme zubereitet.\nVerkaufspreis: \nWeisenfisch Supreme\nBenötigt Stufe 30\n[q2]Benutzen: Stellt im Verlauf von 21 Sek. 292320 Gesundheit und 438134 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und regeneriert 15 Min. lang alle 5 Sekunden 8 Mana.\nVerkaufspreis: \nBenötigt Roher großer Weisenfisch"}
