MultiLanguageItemData['de'][22552] = {name = "Formel: Waffe - Erhebliches Schlagen", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (340)\nBenötigtDas Konsortium\n- Wohlwollend\n[q2]Benutzen: Lehrt Euch7 Nahkampfwaffen dauerhaft zu verzaubern7 sodass ihr Schaden um 7 erhöht wird. Erfordert einen Gegenstand der Stufe 7 oder höher.\n[q2]Eine Nahkampfwaffe dauerhaft verzaubern, sodass damit 7 zusätzlicher Schaden verursacht wird.\nVerkaufspreis:"}
MultiLanguageItemData['de'][22553] = {name = "[q2]Formel: Waffe - Potenz", additional_info = "Benötigt Verzauberkunst (350)\n[q2]Benutzen: Lehrt Euch20 Nahkampfwaffen dauerhaft zu verzaubern20 sodass die Stärke um 20 erhöht wird. Erfordert einen Gegenstand der Stufe 20 oder höher.\n[q2]Eine Nahkampfwaffe dauerhaft verzaubern, sodass die Stärke um 20 erhöht wird.\nVerkaufspreis:"}
MultiLanguageItemData['de'][22554] = {name = "[q2]Formel: Zweihandwaffe - Unbändigkeit", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (350)\n[q2]Benutzen: Lehrt Euch70 Zweihandwaffen dauerhaft zu verzaubern70 sodass die Angriffskraft um 70 erhöht wird. Erfordert einen Gegenstand der Stufe 70 oder höher.\n[q2]Eine Zweihandwaffe dauerhaft verzaubern, sodass die Angriffskraft um 70 erhöht wird.\nVerkaufspreis:"}
MultiLanguageItemData['de'][22555] = {name = "[q2]Formel: Waffe - Erhebliche Zaubermacht", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (350)\n[q2]Benutzen: Lehrt Euch40 Nahkampfwaffen dauerhaft zu verzaubern40 sodass die Zaubermacht um 40 erhöht wird. Erfordert einen Gegenstand der Stufe 40 oder höher.\n[q2]Eine Nahkampfwaffe dauerhaft verzaubern, sodass die Zaubermacht um 40 erhöht wird.\nVerkaufspreis:"}
MultiLanguageItemData['de'][22556] = {name = "[q2]Formel: Zweihandwaffe - Erhebliche Beweglichkeit", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (360)\n[q2]Benutzen: Lehrt Euch35 Zweihandwaffen dauerhaft zu verzaubern35 sodass die Beweglichkeit um 35 erhöht wird. Erfordert einen Gegenstand der Stufe 35 oder höher.\n[q2]Eine Zweihandwaffe dauerhaft verzaubern, sodass die Beweglichkeit um 35 erhöht wird.\nVerkaufspreis:"}
MultiLanguageItemData['de'][22557] = {name = "[q2]Formel: Waffe - Meister des Kampfes", additional_info = "Benötigt Verzauberkunst (360)\n[q2]Benutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, manchmal nahe Gruppenmitglieder um 180 bis 300 geheilt werden, wenn ein Nahkampfangriff durchgeführt wird. Erfordert einen Gegenstand der Stufe 35 oder höher.\n[q2]Eine Nahkampfwaffe dauerhaft verzaubern, sodass sie nahe Gruppenmitglieder gelegentlich um 4800 heilt, wenn ein Nahkampfangriff durchgeführt wird.\nVerkaufspreis:"}
MultiLanguageItemData['de'][22558] = {name = "[q2]Formel: Waffe - Zauberflut", additional_info = "Benötigt Verzauberkunst (360)\n[q2]Benutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass Eure Zauber manchmal bei allen Gruppenmitgliedern in der Nähe 100 Mana wiederherstellen. Erfordert einen Gegenstand der Stufe 35 oder höher.\n[q2]Eine Nahkampfwaffe dauerhaft verzaubern, sodass beim Zauberwirken manchmal bei nahen Gruppenmitgliedern 2000 Mana wiederhergestellt wird.\nVerkaufspreis:"}
MultiLanguageItemData['de'][22559] = {name = "[q3]Formel: Waffe - Mungo", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (375)\n[q2]Benutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass manchmal die Beweglichkeit um 120 und der Tempowert um 30 erhöht wird. Erfordert einen Gegenstand der Stufe 35 oder höher.\n[q2]Eine Nahkampfwaffe dauerhaft verzaubern, sodass gelegentlich Eure Beweglichkeit um 120 und Euer Tempo um 30 erhöht werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][22560] = {name = "[q3]Formel: Waffe - Sonnenfeuer", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (375)\n[q2]Benutzen: Lehrt Euch50 Nahkampfwaffen dauerhaft zu verzaubern50 sodass die Feuer- und Arkanzaubermacht um 50 erhöht wird. Erfordert einen Gegenstand der Stufe 50 oder höher.\n[q2]Eine Nahkampfwaffe dauerhaft verzaubern, sodass die Feuer- und Arkanzaubermacht um 50 erhöht werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][22561] = {name = "[q3]Formel: Waffe - Seelenfrost", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (375)\n[q2]Benutzen: Lehrt Euch54 Nahkampfwaffen dauerhaft zu verzaubern54 sodass die Frost- und Schattenzaubermacht um 54 erhöht wird. Erfordert einen Gegenstand der Stufe 54 oder höher.\n[q2]Eine Nahkampfwaffe dauerhaft verzaubern, sodass die Schatten- und Frostzaubermacht um 54 erhöht werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][22562] = {name = "Formel: Überragendes Manaöl", additional_info = "Benötigt Verzauberkunst (310)\n[q2]Benutzen: Lehrt Euch die Herstellung von überragendem Manaöl.\n[q2]Erstellt Überragendes Manaöl.\nVerkaufspreis: \nÜberragendes Manaöl\nBenötigt Stufe 52\n[q2]Benutzen: Trägt überragendes Manaöl auf Eure Waffe auf, das Eure Willenskraft um 25 erhöht. Hält 1 Stunde lang an. Kann nicht auf Gegenstände über Stufe 200 angewandt werden.\n5 Aufladungen\nVerkaufspreis:\nBenötigt Arkaner Staub (3), Netherblüte , Kristallphiole"}
MultiLanguageItemData['de'][22563] = {name = "Formel: Überragendes Zauberöl", additional_info = "Benötigt Verzauberkunst (340)\n[q2]Benutzen: Lehrt Euch die Herstellung von überragendem Zauberöl.\n[q2]Erstellt Überragendes Zauberöl.\nVerkaufspreis: \nÜberragendes Zauberöl\nBenötigt Stufe 58\n[q2]Benutzen: Trägt überragendes Zauberöl auf Eure Waffe auf, das Eure Intelligenz um 40 erhöht. Hält 1 Stunde lang an. Kann nicht auf Gegenstände über Stufe 200 angewandt werden.\n5 Aufladungen\nVerkaufspreis:\nBenötigt Arkaner Staub (3), Alptraumranke , Kristallphiole"}
MultiLanguageItemData['de'][22564] = {name = "Formel: Arkaner Staub", additional_info = "Benötigt Verzauberkunst (325)\n[q2]Benutzen: Lehrt Euch, einen arkanen Kristall in arkanen Staub umzuwandeln.\n[q2]Wandelt einen Arkankristall in arkanen Staub um.\nVerkaufspreis: \nArkaner Staub\nBenötigt Arkankristall"}
