MultiLanguageItemData['de'][23882] = {name = "[q3]Bauplan: Kleintiervergrößerer", additional_info = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (325)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Kleintiervergrößerers.\nVerkaufspreis: \n[q2]Kleintiervergrößerer\nBenötigt Ingenieurskunst (325)\n[q2]Benutzen: Vergrößert ein Kleintier auf das Doppelte seiner normalen Größe. (15 Sek. Abklingzeit)\n[q]\"Die Anwendungsmöglichkeiten für dieses Gerät sind nahezu unbegrenzt.\"\nVerkaufspreis: \nBenötigt Adamantitrahmen , Eine Handvoll Teufelseisenbolzen (2), Goldkraftkern"}
MultiLanguageItemData['de'][23883] = {name = "[q3]Bauplan: Heiltrankeinspritzung", additional_info = "Benötigt Ingenieurskunst (330)\n[q2]Benutzen: Lehrt Euch die Herstellung einer Heiltrankeinspritzung.\nVerkaufspreis: \nHeiltrankeinspritzung\nBenötigt Stufe 55\n[q2]Benutzen: Stellt 2000 Gesundheit wieder her. Erhöhter Effekt für Ingenieure! (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Teufelseisengehäuse , Eine Handvoll Teufelseisenbolzen , Knotenhautleder (2), Erstklassiger Heiltrank (20)"}
MultiLanguageItemData['de'][23884] = {name = "[q3]Bauplan: Manatrankeinspritzung", additional_info = "Benötigt Ingenieurskunst (345)\n[q2]Benutzen: Lehrt Euch die Herstellung einer Manatrankeinspritzung.\nVerkaufspreis:\nManatrankeinspritzung\nBenötigt Stufe 55\n[q2]Benutzen: Stellt 2400 Mana wieder her. Erhöhter Effekt für Ingenieure! (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Teufelseisengehäuse , Eine Handvoll Teufelseisenbolzen , Knotenhautleder (2), Erstklassiger Manatrank (20)"}
MultiLanguageItemData['de'][23885] = {name = "[q3]Bauplan: Tragbarer Briefkasten", additional_info = "Benötigt Ingenieurskunst (335)\n[q2]Benutzen: Lehrt Euch die Herstellung eines tragbaren Briefkastens.\nVerkaufspreis: \nTragbarer Briefkasten\nBenötigt Ingenieurskunst (335)\n[q2]Benutzen: Entfaltet einen tragbaren Briefkasten, mit dem man Briefe schicken und empfangen kann. Seine Energie reicht 5 Min. lang.\nVerkaufspreis:\nBenötigt Adamantitrahmen , Eine Handvoll Teufelseisenbolzen (2), Khoriumkraftkern , Verschmorte Verkabelung"}
