MultiLanguageItemData['de'][32898] = {name = "Fläschchen der Stärkung aus Shattrath", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 70\n[q2]Benutzen: Erhöht 1 Stunde lang die maximale Gesundheit um 500 und das Ausweichen um 10. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\n Wirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau. (3 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][32899] = {name = "Fläschchen der mächtigen Wiederherstellung aus Shattrath", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 70\n[q2]Benutzen: Erhöht die Willenskraft 1 Stunde lang um 62 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\n Wirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau. (3 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][32900] = {name = "Fläschchen der obersten Macht aus Shattrath", additional_info = "Wird beim Aufheben gebunden\nBenötigt Stufe 70\n[q2]Benutzen: Erhöht die Schadenswirkung von Zaubern und magischen Effekten 1 Stunde lang um bis zu 70. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\n Wirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau. (3 Sek. Abklingzeit)"}
