MultiLanguageItemData['de'][40896] = {name = "Glyphe 'Rasende Regeneration'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Druide\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nNach der Aktivierung von 'Rasende Regeneration' sind auf Euch gewirkte Heileffekte 6 Sek. lang 40% mächtiger. Allerdings kostet Eure 'Rasende Regeneration' nun immer 50 Wut und wandelt Wut nicht mehr in Gesundheit um.\nVerkaufspreis:"}
