MultiLanguageItemData['de'][41091] = {name = "Handmontierte Pyrorakete", additional_info = "Benötigt Ingenieurskunst (375)\n[q2]Benutzen: Bringt an einem Paar Handschuhe dauerhaft einen Pyroraketenwerfer an, der es einem geschickten Ingenieur gestattet, eine Rakete abzuschießen, die auf Distanz ( 106 * 10) bis ( 128 * 10) Feuerschaden verursacht. Kann nur einmal alle 45 Sek. abgefeuert werden.\n\n Kann nur an Eure eigenen Handschuhe angebracht werden und sie werden dadurch seelengebunden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][41092] = {name = "Glyphe 'Doppelbestrafung'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr Euren Zauber 'Richturteil' auf ein Ziel wirkt, wird der Schaden des nächsten Wirkens von 'Richturteil' auf ein zweites Ziel um 20% erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][41093] = {name = "Hypergeschwindigkeitsbeschleuniger", additional_info = "Benötigt Ingenieurskunst (375)\n[q2]Benutzen: Erhöht Euer Tempo 12 Sek. lang um 240 . (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][41094] = {name = "Glyphe 'Aura der Hingabe'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure 'Aura der Hingabe' wirkt nicht mehr auf Gruppen- und Schlachtzugsmitglieder, die Abklingzeit wird aber um 60 Sek. verringert.\nVerkaufspreis:"}
MultiLanguageItemData['de'][41095] = {name = "Glyphe 'Heiliger Zorn'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Heiliger Zorn' betäubt auch Elementare, Drachkin und Entartungen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][41096] = {name = "Glyphe 'Göttlicher Schutz'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nReduziert den Magieschaden verringernden Effekt Eures Zaubers 'Göttlicher Schutz' auf 20%, lässt ihn dafür aber zusätzlich den erlittenen körperlichen Schaden um 20% verringern.\nVerkaufspreis:"}
MultiLanguageItemData['de'][41097] = {name = "Glyphe 'Urteil des Templers'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nNachdem Ihr mit 'Urteil des Templers' oder 'Exorzismus' Schaden verursacht habt, erleidet Ihr 6 Sek. lang 10% weniger Schaden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][41098] = {name = "Glyphe 'Zornige Vergeltung'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Euer Zauber 'Zornige Vergeltung' aktiv ist, werdet Ihr alle 2 Sek. um 1 % Eurer maximalen Gesundheit geheilt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][41099] = {name = "Glyphe 'Weihe'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr könnt nun den Effektbereich Eures Zaubers 'Weihe' in einem Umkreis von 25 Metern frei platzieren.\nVerkaufspreis:"}
