MultiLanguageItemData['de'][41101] = {name = "Glyphe 'Fokussierter Schild'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Schild des Rächers' trifft 2 Ziele weniger, verursacht jedoch 30% mehr Schaden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][41102] = {name = "Glyphe 'Bürde der Schuld'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nTreffer Eures Zaubers 'Richturteil' erfüllen Euer Ziel mit Zweifeln und Reue, die sein Bewegungstempo 2 Sek. lang um 50% verringern.\nVerkaufspreis:"}
MultiLanguageItemData['de'][41103] = {name = "Glyphe 'Blendendes Licht'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Blendendes Licht' stößt Ziele 3 Sek. lang zu Boden, statt sie zu blenden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][41104] = {name = "Glyphe 'Unaufhaltsamer Zorn'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Heiliger Zorn' fügt Zielen, die über weniger als 20% Gesundheit verfügen, 50% mehr Schaden zu.\nVerkaufspreis:"}
MultiLanguageItemData['de'][41105] = {name = "Glyphe 'Wort der Herrlichkeit'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den Schaden pro verbrauchter heiliger Kraft nach dem Wirken von 'Wort der Herrlichkeit' oder 'Ewige Flamme' auf ein verbündetes Ziel um 3%. Hält 6 Sek. lang an.\nVerkaufspreis:"}
MultiLanguageItemData['de'][41106] = {name = "Glyphe 'Illumination'", additional_info = "Klassen: Paladin\nBenötigt Stufe 25\n[q2]Benutzen:\n[q2]Kritische Effekte Eures Zaubers 'Heiliger Schock' regenerieren sofort 1% Eures Manas, Euer passiver Effekt 'Meditation' regeneriert jedoch 10% weniger Mana.\nVerkaufspreis:"}
MultiLanguageItemData['de'][41107] = {name = "Glyphe 'Mahnende Worte'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Paladin\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Wort der Herrlichkeit' kann jetzt gegen gegnerische Ziele eingesetzt werden und fügt ihnen Heiligschaden in etwa der Höhe der ansonsten geheilten Menge zu.\n\n Funktioniert nicht mit 'Ewige Flamme'.\nVerkaufspreis:"}
