MultiLanguageItemData['de'][42401] = {name = "Glyphe 'Heilige Nova'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch den Zauber 'Heilige Nova'.\n\n Löst eine Explosion heiligen Lichts um den Zaubernden aus, die allen Gegnern im Umkreis von 10 Metern 13 Heiligschaden zufügt und bis zu 5 Verbündete in einem Umkreis von 10 Metern um 20 heilt.\n\n Die Heilung wird unter allen geheilten Zielen aufgeteilt. Diese Effekte erzeugen keine Bedrohung.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42402] = {name = "Glyphe 'Inneres Feuer'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die von Eurem Zauber 'Inneres Feuer' gewährte Rüstung um 50%.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42403] = {name = "Glyphe 'Tiefe Brunnen'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Anzahl der Aufladungen Eures Lichtbrunnens um 2.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42404] = {name = "Glyphe 'Massenbannung'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Massenbannung' wird mächtig genug, magische Effekte zu entfernen, die normalerweise nicht gebannt werden können.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42405] = {name = "Glyphe 'Psychisches Entsetzen'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eures Zaubers 'Psychisches Entsetzen' um 10 Sek.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42406] = {name = "Glyphe 'Heiliges Feuer'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Reichweite Eurer Zauber 'Heiliges Feuer', 'Heilige Pein' und 'Machtwort: Trost' um 10 Meter.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42407] = {name = "Glyphe 'Geschwächte Seele'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Dauer des vom Zauber 'Machtwort: Schild' ausgelösten Effekts 'Geschwächte Seele' um 2 Sek.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42408] = {name = "Glyphe 'Machtwort: Schild'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWandelt 20% des Absorptionswertes Eures Zaubers 'Machtwort: Schild' in Heilung um.\nVerkaufspreis:"}
