MultiLanguageItemData['de'][42410] = {name = "Glyphe 'Psychischer Schrei'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nDie Ziele Eures Zaubers 'Psychischer Schrei' sowie des Zaubers 'Psychoterror' Eures Psychoschreckens erstarren nun vor Furcht, anstatt zu flüchten.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42411] = {name = "Glyphe 'Erneuerung'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nDer geheilte Wert jedes Ticks Eures Zaubers 'Erneuerung' wird um 33% erhöht, die Gesamtdauer des Effekts wird jedoch um 3 Sek. verringert.\nVerkaufspreis:"}
