MultiLanguageItemData['de'][42415] = {name = "Glyphe 'Magiebannung'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Magiebannung' fügt Eurem Ziel zusätzlich 30 Heiligschaden zu, wenn erfolgreich ein magischer Stärkungszauber gebannt wurde.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42416] = {name = "Glyphe 'Heilige Pein'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Heilige Pein' verursacht 20% zusätzlichen Schaden, wenn das Ziel vom Effekt Eures Zaubers [ Trost und Wahnsinn : 'Machtwort: Trost' / 'Heiliges Feuer'] betroffen ist. Der zusätzliche Schaden hat keinen Einfluss auf 'Abbitte'.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42417] = {name = "Glyphe 'Gebet der Besserung'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nDas erste Ziel Eures Zaubers 'Gebet der Besserung' wird um zusätzliche 60% geheilt, der Zauber hat jedoch insgesamt 1 Aufladung weniger.\nVerkaufspreis:"}
