MultiLanguageItemData['de'][42453] = {name = "Glyphe 'Hand von Gul'dan'", additional_info = "[q9]Geringe Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Hand von Gul'dan' kann auf eine Position gezielt eingesetzt werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42454] = {name = "Glyphe 'Feuersbrunst'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\n'Feuersbrunst' setzt nicht mehr voraus, dass das Ziel von 'Feuerbrand' betroffen ist, um es zu verlangsamen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42455] = {name = "Glyphe 'Lebensentzug'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber [ Feuerbrand : 'Feuerbrand' ] 'Verderbnis' heilt Euch um 0.5% Eurer Maximalgesundheit, wenn er [ Feuerbrand : regelmäßigen ] Schaden verursacht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42456] = {name = "Glyphe 'Tiefgrüne Sphären'", additional_info = "[q9]Geringe Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\n[ Zerstörung : Aktive instabile Funken werden als grüne Sphären dargestellt, die um Euren Charakter wirbeln /\n\nGebrechen, Dämonologie\nEure Seelensplitter werden in grüne Sphären umgewandelt ]\nVerkaufspreis:"}
MultiLanguageItemData['de'][42457] = {name = "Glyphe 'Alpträume'", additional_info = "[q9]Geringe Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Teufelsross und Euer Schreckensross können übers Wasser hinwegreiten und hinterlassen eine Flammenspur.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42458] = {name = "Glyphe 'Furcht'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nLässt das Ziel Eures Zaubers 'Furcht' vor Furcht erstarren, anstatt dass es flüchtet.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42459] = {name = "Glyphe 'Teufelswache'", additional_info = "[q9]Geringe Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Teufelswache wird sich mit einer zufälligen Waffe der folgenden Arten ausrüsten, die sich in Euren Taschen befindet: Zweihandaxt, Zweihandschwert oder Stangenwaffe.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42460] = {name = "Glyphe 'Dämonisches Training'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerbessert die Spezialfähigkeiten Eures Dämons:\n\n Verringert die Zauberzeit des Zaubers 'Feuerblitz' Eures [ Grimoire der Überlegenheit : Teufelswichtels / Wichtels] um 50% und es werden 3 Blitze abgefeuert.\n\n Erhöht die gesamte Rüstung Eures [ Grimoire der Überlegenheit : Leerenfürsten / Leerwandlers] um 10%.\n\n Die Fähigkeit [ Grimoire der Überlegenheit : 'Mesmerisieren' / 'Verführung'] [ Grimoire der Überlegenheit : Eurer Shivarra / Eures Succubus] entfernt zusätzlich alle regelmäßigen Schadenseffekte vom Ziel.\n\n Wenn Euer [ Grimoire der Überlegenheit : Beobachter / Teufelsjäger] die Fähigkeit [ Grimoire der Überlegenheit : 'Magie kopieren' / 'Magie verschlingen'] einsetzt, werdet Ihr um die gleiche Menge geheilt.\n\n Erhöht die gesamte Gesundheit [ Grimoire der Überlegenheit : Eures Zornwächters / Eurer Teufelswache] um 20%.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42461] = {name = "Glyphe 'Lebenslinie'", additional_info = "[q9]Geringe Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Lebenslinie' stellt sofort 15 % der Gesundheit Eures Dämons wieder her, hat jedoch eine Abklingzeit von 10 Sek.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42462] = {name = "Glyphe 'Gesundheitsstein'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr gewinnt durch das Nutzen von Gesundheitssteinen 100% mehr Gesundheit, der Effekt wird jedoch zu einer regelmäßigen Heilung, die im Verlauf von 10 Sek. erfolgt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42463] = {name = "Glyphe 'Subtilität'", additional_info = "[q9]Geringe Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Seelensplitter werden außerhalb des Kampfes nicht mehr angezeigt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42464] = {name = "Glyphe 'Fluch der Elemente'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Fluch der Elemente' trifft 2 zusätzliche Ziele in der Nähe.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42465] = {name = "Glyphe 'Wichtelschwarm'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nBenötigt Dämonologie.\n Lehrt Euch den Zauber 'Wichtelschwarm'.\n\n Wichtelschwarm\nBeschwört 4 Wildwichtel aus dem Wirbelnden Nether, die das Ziel angreifen.\n\n Der passive Effekt von 'Wildwichtel' ist inaktiv, während der Zauber abklingt. Die Abklingzeit von 'Wichtelschwarm' wird von Tempo verringert. Erhöht außerdem die Abklingzeit von 'Wildwichtel' um 4 Sek.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42466] = {name = "Glyphe 'Verwüstung'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nDer Zauber 'Verwüstung' erhält 3 zusätzliche Aufladungen, die Abklingzeit wird jedoch um 35 Sek. erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42467] = {name = "Glyphe 'Schattenblitz'", additional_info = "[q9]Geringe Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nTeilt Euren Schattenblitz in drei kleinere Geschosse auf.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42468] = {name = "[q0]Verblichene Glyphe", additional_info = "Klassen: Hexenmeister\n[q]\"Die Magie dieser Glyphe ist verflogen, aber die Inschrift ist immer noch wunderschön anzusehen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][42469] = {name = "[q0]Verkohlte Glyphe", additional_info = "[q]\"Es sieht zwar aus, als wäre diese Glyphe entsetztlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][42470] = {name = "Glyphe 'Seelenstein'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nSpielercharaktere, die sich durch einen Seelenstein wiederbeleben, erstehen mit 100% Gesundheit auf.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42471] = {name = "Glyphe 'Aasschwarm'", additional_info = "[q9]Geringe Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Aasschwarm' stößt Ziele nicht mehr zurück.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42472] = {name = "Glyphe 'Instabiles Gebrechen'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Zauberzeit von 'Instabiles Gebrechen' um 25%.\nVerkaufspreis:"}
