MultiLanguageItemData['de'][42898] = {name = "Glyphe 'Camouflage'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Camouflage' gewährt Euch nun selbst wenn Ihr Euch bewegt einen Verstohlenheitseffekt, Euer Bewegungstempo wird, während die Fähigkeit aktiv ist, jedoch um 50% verringert.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42899] = {name = "Glyphe 'Befreiung'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr Eure Fähigkeit 'Rückzug' nutzt, werdet Ihr um 5 % Eurer gesamten Gesundheit geheilt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42900] = {name = "Glyphe 'Besserung'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Tier heilen' heilt jetzt alle 1 Sek. und heilt zusätzliche 25% der Gesundheit Eures Begleiters im Verlauf seiner Dauer.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42901] = {name = "Glyphe 'Ablenkender Schuss'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Ablenkender Schuss' lenkt die Aufmerksamkeit des Ziel nun auf Euer Tier statt auf Euch.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42902] = {name = "Glyphe 'Endloser Zorn'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend 'Zorn des Wildtiers' aktiv ist, kann Euer Tier zwar Schaden erleiden aber nicht getötet werden.\nVerkaufspreis:"}
