MultiLanguageItemData['de'][42904] = {name = "Glyphe 'Rückzug'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Rückstoßentfernung von 'Rückzug'.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42905] = {name = "Glyphe 'Eiskältefalle'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEndet der Effekt Eurer Eiskältefalle, wird das Bewegungstempo des Ziels 4 Sek. lang um 70% verringert.\nVerkaufspreis:"}
