MultiLanguageItemData['de'][42907] = {name = "Glyphe 'Irreführung'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr Eure Fähigkeit 'Irreführung' auf Euer Tier anwendet, wird die Abklingzeit von 'Irreführung' sofort abgeschlossen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][42908] = {name = "Glyphe 'Sprengfalle'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Sprengfalle verursacht keinen Schaden mehr, sondern stößt stattdessen bei der Explosion der Falle alle im Effektbereich befindlichen Gegner zurück.\nVerkaufspreis:"}
