MultiLanguageItemData['de'][43418] = {name = "Glyphe 'Auf die Kehle zielen'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Krieger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeiten 'Zuschlagen' und 'Heldenhafter Wurf' bringen das Ziel zusätzlich 3 Sek. lang zum Schweigen. Funktioniert nicht gegen Spielercharaktere.\nVerkaufspreis:"}
MultiLanguageItemData['de'][43419] = {name = "Glyphe 'Blitz'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Krieger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Sturmangriff' [ Kriegstreiber : macht Ziele in der Nähe bewegungsunfähig und verringert ihr Bewegungstempo / betäubt Ziele in der Nähe]. Wirkt sich auf bis zu 2 zusätzliche Ziele aus.\nVerkaufspreis:"}
MultiLanguageItemData['de'][43420] = {name = "[q0]Verkohlte Glyphe", additional_info = "[q]\"Es sieht zwar aus, als wäre diese Glyphe entsetztlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43421] = {name = "Glyphe 'Tödlicher Stoß'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Krieger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Eure Fähigkeit 'Tödlicher Stoß' auf einem Ziel aktiv ist, sind Heileffekte auf Euch um 10% erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][43422] = {name = "Glyphe 'Durch das Schwert umkommen'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Krieger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend 'Durch das Schwert umkommen' aktiv ist, erhöht der Einsatz von 'Überwältigen' die Dauer des Effekts um 1 Sek. und der Einsatz von 'Wilder Stoß' erhöht die Dauer um 0.5 Sek. pro Anwendung.\nVerkaufspreis:"}
MultiLanguageItemData['de'][43423] = {name = "Glyphe 'Kniesehne'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Krieger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr Wut ausgebt, um Eure Fähigkeit 'Kniesehne' einzusetzen, werden die Wutkosten des nächsten Einsatzes von 'Kniesehne' um 100% verringert.\nVerkaufspreis:"}
MultiLanguageItemData['de'][43424] = {name = "Glyphe 'Stellung halten'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Krieger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den verursachten Schaden des nächsten Einsatzes Eurer Fähigkeit 'Rache' um 50%, nachdem Ihr einen Angriff pariert habt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][43425] = {name = "Glyphe 'Schildschlag'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Krieger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Schildschlag' bannt nun 1 magischen Effekt auf dem Ziel.\nVerkaufspreis:"}
