MultiLanguageItemData['de'][43428] = {name = "Glyphe 'Weitreichende Stöße'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Krieger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr Ziele mit Eurer Fähigkeit 'Weitreichende Stöße' trefft, erhaltet Ihr 1 Wut.\nVerkaufspreis:"}
