MultiLanguageItemData['de'][43628] = {name = "Lady Jaina Prachtmeers Goldmünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n[q]\"Arthas, mein Liebster, bitte komm zu mir zurück.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43629] = {name = "Uther Lichtbringers Goldmünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n[q]\"Der junge Arthas muss Geduld lernen und seine Macht im Zaum halten. Ich werde dafür beten, dass er eines Tages lernen wird, mit Fürsorge statt mit Gewalt zu gebieten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43630] = {name = "Tirion Fordrings Goldmünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n[q]\"Ich wünsche mir, dass mein teurer Taelan stark genug werden wird, um diejenigen zu schützen, die ihm am Herzen liegen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43631] = {name = "Terons Goldmünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n[q]\"Wünsche sind ein Zeitvertreib für Toren. Nehmt diese Münze als Lohn für Euer kostbares Auge.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43632] = {name = "Sylvanas Windläufers Goldmünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n[q]\"Ich hoffe, dass meine Schwestern und ich gemeinsam aufwachsen und gemeinsam heiraten können. Diese Münze scheint sehr alt zu sein.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43633] = {name = "Prinz Kael'thas Sonnenwanderers Goldmünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n[q]\"Dieser junge Lehrling namens Jaina ist ziemlich attraktiv für einen Menschen. Ich hoffe, dass sie erkennt, wie elegant und mächtig ich bin.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43634] = {name = "Lady Katrana Prestors Goldmünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n[q]\"Hör mir zu, kleiner Wunschbrunnen. Wenn du weißt, was gut für dich ist, dann wirst du mir all deine Macht geben.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43635] = {name = "Kel'Thuzads Goldmünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n[q]\"Manchmal... wünschte ich, dass mich irgendjemand mal ganz lang umarmen würde.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43636] = {name = "Chromies Goldmünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n[q]\"Ich wünschte, dass mich jemand nur ein einziges Mal grüßen würde, ohne dabei einen dummen Witz über Gnome oder Zeitreisen machen zu müssen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43637] = {name = "Brann Bronzebarts Goldmünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n[q]\"Brann Bronzebart war hier.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43638] = {name = "Arugals Goldmünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n[q]\"Eines Tages möchte ich mich in meinem eigenen sauberen, kleinen Anwesen mit ein paar Hunden an meiner Seite niederlassen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43639] = {name = "Arthas' Goldmünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n[q]\"Ich habe schon ein Königreich in Aussicht; ein Land, über das ich herrschen kann. Was will ich mehr? Ein richtig langer Winterurlaub, das wär' was...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43640] = {name = "Archimondes Goldmünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n[q]\"Ich möchte wissen, wie du meinen Zorn überstehen konntest, kleiner Brunnen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43641] = {name = "Anduin Wrynns Goldmünze", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n[q]\"Wünschte, ich würde endlich mal erwachsen werden. Hab' das Gefühl, dass ich schon seit 'ner Ewigkeit zehn bin.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43643] = {name = "[q0]Prinz Magni Bronzebarts Silbermünze", additional_info = "[q]\"Ich hoffe, dass mein Vater und Bruder länger leben werden als ich. Ich würde keinen so guten König abgeben.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43644] = {name = "[q0]Silbermünze eines Bauern", additional_info = "[q]\"Ich bin so vergesslich! Wünschte, mein Gedächtnis wäre besser. Halt, habe ich nicht schon 'ne Münze hier reingeworfen?\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43645] = {name = "[q0]Verbogener Angelhaken", additional_info = "[q]\"Sieht so aus, als hätte jemand versucht, in dem Brunnen herumzufischen. Wer würde so etwas nur tun?\"\nVerkaufspreis:"}
