MultiLanguageItemData['de'][43668] = {name = "Leylinienempfänger", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Ihr seid Euch nicht so ganz sicher, was Ihr davon halten sollt. Er steckt auf jeden Fall voller arkaner Magie. Doch wie kann etwas so Kleines nur so wichtig sein?\""}
MultiLanguageItemData['de'][43669] = {name = "Medaillon der verstorbenen Königin", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Die einzige Erinnerung, die König Ymiron an seine Geliebte, Königin Angerboda, hatte.\""}
MultiLanguageItemData['de'][43670] = {name = "Verzaubertes Tiki des Propheten", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Mit dem Ableben seines Trägers scheint es auch all sein Mojo verloren zu haben.\""}
MultiLanguageItemData['de'][43671] = {name = "Glyphe 'Eisige Pfade'", additional_info = "[q9]Geringe Glyphe\nKlassen: Todesritter\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Eisige Pfade' ermöglicht Euch, von größeren Höhen zu fallen ohne Schaden zu erleiden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][43672] = {name = "Glyphe 'Unnachgiebiger Griff'", additional_info = "[q9]Geringe Glyphe\nKlassen: Todesritter\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Eure Fähigkeit 'Todesgriff' fehlschlägt, weil das Ziel dagegen immun ist, wird ihre Abklingzeit zurückgesetzt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][43673] = {name = "Glyphe 'Schwarzes Tor'", additional_info = "[q9]Geringe Glyphe\nKlassen: Todesritter\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Zauberzeit Eures Zaubers 'Schwarzes Tor' um 60%.\nVerkaufspreis:"}
MultiLanguageItemData['de'][43674] = {name = "Glyphe 'Spurt'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Druide\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eurer Fähigkeit 'Spurt' um 60 Sek.\nVerkaufspreis:"}
MultiLanguageItemData['de'][43675] = {name = "[q0]Fandral Hirschhaupts Silbermünze", additional_info = "[q]\"Der Krieg der Sandstürme... Wünschte, ich könnte vergessen, dass er jemals stattgefunden hat.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43676] = {name = "[q0]Arkanist Doans Silbermünze", additional_info = "[q]\"Oh, wieso wollt Ihr mir einfach keine Beachtung schenken? Ich würde Euch überall hin folgen, Abbendis. Ich wünschte, Ihr würdet mich zur Kenntnis nehmen...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43677] = {name = "[q0]Hochtüftler Mekkadrills Silbermünze", additional_info = "[q]\"Wie kann dieser Brunnen nur funktionieren? Ich frage mich, ob ich selbst einen bauen könnte.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43678] = {name = "[q0]Antonidas Silbermünze", additional_info = "[q]\"Gib mir die Stärke, Dinge hinzunehmen, die ich nicht ändern kann, den Mut, Dinge zu ändern, die ich ändern kann, und die Weisheit, das eine vom anderen zu unterscheiden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43679] = {name = "[q0]Muradin Bronzebarts Silbermünze", additional_info = "[q]\"Möge uns das Heilige Licht auf unserer Expedition in den eisigen Norden beschützen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43680] = {name = "[q0]König Varian Wrynns Silbermünze", additional_info = "[q]\"Ich wünschte, der Aufstand zuhause würde sich bald wieder legen. Würde nicht wollen, dass irgendjemand verletzt wird.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43681] = {name = "[q0]König Terenas Menethils Silbermünze", additional_info = "[q]\"Möge mein Sohn Arthas immer im besten Interesse seines Volkes handeln.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43682] = {name = "[q0]König Anasterian Sonnenwanderers Silbermünze", additional_info = "[q]\"Ich hoffe, der junge Kael'thas ist sich bewusst, dass er eines Tages unser Volk führen muss.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43683] = {name = "[q0]Khadgars Silbermünze", additional_info = "[q]\"Turalyon und Alleria, wo auch immer Ihr seid, möge es Euch wohl ergehen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43684] = {name = "[q0]Medivhs Silbermünze", additional_info = "[q]\" \"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43685] = {name = "[q0]Maiev Schattensangs Silbermünze", additional_info = "[q]\"Wo ist Illidan?\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43686] = {name = "[q0]Allerias Silbermünze", additional_info = "[q]\"Mögen meine Schwestern ihr volles Potential erkennen; mögen ihre Taten den Namen Windläufer bekannt machen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][43687] = {name = "[q0]Aegwynns Silbermünze", additional_info = "[q]\"Ich wünschte wirklich, dass Ihr Magier endlich damit aufhören würdet, die Köpfe in Eure eigenen... Bücher zu stecken.\"\nVerkaufspreis:"}
