MultiLanguageItemData['de'][44953] = {name = "Worgtatar", additional_info = "Benötigt Stufe 70\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. 22502 Gesundheit und ( 3200 / 5 * 30) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 40 Trefferwert und 40 Ausdauer.\nVerkaufspreis:"}
MultiLanguageItemData['de'][44954] = {name = "[q2]Rezept: Worgtatar", additional_info = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (400)\n[q2]Benutzen: Lehrt Euch, wie man Worgfleisch zu Worgtatar zerkleinert.\n[q2]Diese Delikatesse wird am besten roh serviert und benötigt deshalb keine Kochstelle.\n\n\nWorgtatar\nBenötigt Stufe 70\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. 22502 Gesundheit und ( 3200 / 5 * 30) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 40 Trefferwert und 40 Ausdauer.\nVerkaufspreis:\nBenötigt Worgschenkel (2), Nordische Gewürze"}
