MultiLanguageItemData['de'][45731] = {name = "Glyphe 'Einlullender Schuss'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Einlullender Schuss' kostet keinen Fokus mehr, hat jedoch eine Abklingzeit von 10 Sek.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45732] = {name = "Glyphe 'Aspekt des Geparden'", additional_info = "[q9]Geringe Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nIst Eure Fähigkeit 'Aspekt des Geparden' aktiv, werdet Ihr nicht mehr benommen, wenn Ihr getroffen werdet. Stattdessen wird der Effekt abgebrochen und alle Eure Aspekte werden mit einer Abklingzeit von 4 Sek. belegt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45733] = {name = "Glyphe 'Ruf des Meisters'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Dauer Eurer Fähigkeit 'Ruf des Meisters' um 4 Sek.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45734] = {name = "Glyphe 'Streuschuss'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Reichweite der Fähigkeit 'Streuschuss' um 3 Meter.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45735] = {name = "Glyphe 'Spiegelnde Klingen'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Jäger\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr einen Zaubertreffer erleidet, während 'Abschreckung' aktiv ist, besteht eine Chance von 100%, dass der Zauber auf den Zaubernden reflektiert wird.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45736] = {name = "Glyphe 'Wasserelementar'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Magier\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Gesundheit Eures Wasserelementars um 40% und ermöglicht es ihm, Zauber während der Bewegung zu wirken. Im Hilfsmodus im Kampf bewirkt der Befehl 'Folgen', dass er in Eurer Nähe bleibt und automatisch 'Wasserblitz' wirkt, wenn ein Ziel in Reichweite gelangt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45737] = {name = "Glyphe 'Verlangsamen'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Magier\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Arkanschlag' belegt ein beliebiges Ziel, dem er Schaden zufügt, mit dem Effekt Eures Zaubers 'Verlangsamen', soweit zu diesem Zeitpunkt kein anderes Ziel mit Eurem Zauber 'Verlangsamen' belegt ist.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45738] = {name = "Glyphe 'Illusion'", additional_info = "[q9]Geringe Glyphe\nKlassen: Magier\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch die Fähigkeit 'Illusion'.\n\n Lässt Euch 2 Min. lang das Aussehen von jemand anderem annehmen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45739] = {name = "Glyphe 'Spiegelbild'", additional_info = "[q9]Geringe Glyphe\nKlassen: Magier\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Spiegelbilder wirken, abhängig von Eurem primären Talentbaum, 'Arkanschlag' oder 'Feuerball' statt 'Frostblitz'.\nVerkaufspreis:"}
