MultiLanguageItemData['de'][45755] = {name = "Glyphe 'Glaubenssprung'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Glaubenssprung' entfernt nun alle bestehenden bewegungeinschränkenden Effekte vom Ziel.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45756] = {name = "Glyphe 'Sühne'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Manakosten von 'Sühne' um 20%, Ihr könnt den Zauber jedoch während des Laufens wirken.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45757] = {name = "Glyphe 'Gebündelte Besserung'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\n'Gebet der Besserung' springt nur noch zwischem dem Ziel und dem Zaubernden hin und her.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45758] = {name = "Glyphe 'Gedankenstachel'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErfolgreiches Wirken von 'Gedankenstachel' mit Zauberzeit verringert die Zauberzeit Eures nächsten Wirkens von 'Gedankenschlag' innerhalb von 9 Sek. um 50%. Dieser Effekt ist bis zu 2-mal stapelbar.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45760] = {name = "Glyphe 'Verbindende Heilung'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Verbindende Heilung' heilt nun ein drittes Ziel innerhalb von 20 Metern, die Manakosten werden jedoch um 35% erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45761] = {name = "Glyphe 'Vendetta'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Schurke\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert den Schadensbonus Eurer Fähigkeit 'Vendetta' um 5%, erhöht jedoch ihre Dauer um 10 Sek.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45762] = {name = "Glyphe 'Mordlust'", additional_info = "[q9]Geringe Glyphe\nKlassen: Schurke\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn der Effekt Eurer Fähigkeit 'Mordlust' endet, werdet Ihr an Euren Anfangspunkt zurückversetzt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45764] = {name = "Glyphe 'Verstohlenheit'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Schurke\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eurer Fähigkeit 'Verstohlenheit' um 4 Sek.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45765] = {name = "Schwarze Kavallerieklinge", additional_info = "Eiskrone\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand\n{4 - 8 Schaden} {Tempo 3.00}\n(2.00 Schaden pro Sekunde)\nHaltbarkeit 16 / 16\nBenötigt Stufe 77"}
