MultiLanguageItemData['de'][45779] = {name = "Glyphe 'Blutsauger'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die durch Euren Zauber 'Blutsauger' erzeugte Heilung um 30%.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45780] = {name = "Glyphe 'Dämonenjagd'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nBenötigt Dämonologie.\n\n Lehrt Euch den Zauber ' Dunkle Apotheose '.\n\nDunkle Apotheose\nDurchtränkt Euch mit dämonischen Energien, die Euren erlittenen körperlichen Schaden um 13.85% und den erlittenen Magieschaden um 15% verringern sowie den Einsatz verschiedener Dämonenfähigkeiten gestatten.\n\n Zusätzlich wird Euer Zauber 'Seele brechen' zu 'Provokation', der Euer Ziel verspottet. Außerdem wird Euer Zauber 'Zwielichtzauberschutz' zu 'Zornbarriere', der alle Zauberarten absorbiert, Euer Zauber 'Schattenblitz' wird zu 'Dämonischer Hieb' und Euer Zauber 'Furcht' wird zu 'Schlaf'.\nVerkaufspreis:"}
MultiLanguageItemData['de'][45781] = {name = "Glyphe 'Funkenwandlung'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die durch Euren Zauber 'Funkenwandlung' erzeugte Heilung um zusätzlich 5% Eurer Gesundheit, die Gesundheit wird jedoch über einen Zeitraum von 10 Sek. regeneriert.\nVerkaufspreis:"}
