MultiLanguageItemData['de'][46710] = {name = "Rezept: Totenspeise", additional_info = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (1)\nBenötigtTag der Toten\n[q2]Benutzen: Lehrt Euch, wie man Totenspeise backt.\nVerkaufspreis:\nTotenspeise\nBenötigtTag der Toten\n[q2]Benutzen: Stellt 30 Sek. lang 99600 Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt, was alle Eure Werte 1 Stunde lang um 108 erhöht.\nVerkaufspreis:\nBenötigt Herkömmliches Mehl , Eiskalte Milch"}
MultiLanguageItemData['de'][46711] = {name = "Seelenkerze", additional_info = "Wird beim Aufheben gebunden\nBenötigtTag der Toten\n[q2]Benutzen: Platziert eine Seelenkerze, welche die Willenskraft aller in der Nähe um 4 erhöht. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][46714] = {name = "Halgas 'Straßenfeger'", additional_info = "Questgegenstand\n[q]\"Die Läufe dieser monströsen Waffe sind fast so dick, wie Eure Faust. Sie kann nur von einem Karawanenkodo aus angewendet werden.\""}
