MultiLanguageItemData['de'][46803] = {name = "Rezept: Gewürzbrotfüllung", additional_info = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (1)\n[q2]Benutzen: Lehrt Euch, wie man Gewürzbrotfüllung zubereitet.\n\n\nGewürzbrotfüllung\nBenötigtPilgerfreudenfest\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Trefferwert und Ausdauer werden 1 Stunde lang um [floor(cond($GT( 90, 15), 90 - 15, 0) * 0.554) + 4] erhöht.\nVerkaufspreis:\nBenötigt Gewürzbrot , Herbstliche Gewürze"}
MultiLanguageItemData['de'][46804] = {name = "Rezept: Kürbiskuchen", additional_info = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (100)\n[q2]Benutzen: Lehrt Euch, wie man Kürbiskuchen zubereitet.\n\n\nKürbiskuchen\nBenötigtPilgerfreudenfest\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und 1 Stunde lang Eure Willenskraft und Ausdauer um [floor(cond($GT( 90, 15), 90 - 15, 0) * 0.554) + 4] erhöht.\nVerkaufspreis:\nBenötigt Reifer Tirisfalkürbis , Honig"}
MultiLanguageItemData['de'][46805] = {name = "Rezept: Moosbeerenchutney", additional_info = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (160)\n[q2]Benutzen: Lehrt Euch, wie man Moosbeerenchutney zubereitet.\n\n\nMoosbeerenchutney\nBenötigtPilgerfreudenfest\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und 1 Stunde lang Eure Zaubermacht um [floor(cond($GT( 90, 15), 90 - 15, 0) * 0.6616) + 4] und Eure Ausdauer um [floor(cond($GT( 90, 15), 90 - 15, 0) * 0.554) + 4] erhöht.\nVerkaufspreis:\nBenötigt Säuerliche Moosbeeren vom Südstrom , Honig"}
MultiLanguageItemData['de'][46806] = {name = "Rezept: Kandierte Süßkartoffel", additional_info = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (220)\n[q2]Benutzen: Lehrt Euch, wie man kandierte Süßkartoffeln zubereitet.\n\n\nKandierte Süßkartoffel\nBenötigtPilgerfreudenfest\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Tempo und Ausdauer werden 1 Stunde lang um [floor(cond($GT( 90, 15), 90 - 15, 0) * 0.8) + 4] erhöht.\nVerkaufspreis:\nBenötigt Süßkartoffel aus Mulgore , Honig , Herbstliche Gewürze"}
MultiLanguageItemData['de'][46807] = {name = "Rezept: Langsam gerösteter Truthahn", additional_info = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (280)\n[q2]Benutzen: Lehrt Euch, wie man langsam gerösteten Truthahn zubereitet.\n\n\nLangsam gerösteter Truthahn\nBenötigtPilgerfreudenfest\n[q2]Benutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und 1 Stunde lang Eure Angriffskraft um [floor(cond($GT( 90, 15), 90 - 15, 0) * 1.108) + 8] und Eure Ausdauer um [floor(cond($GT( 90, 15), 90 - 15, 0) * 0.554) + 4] erhöht.\nVerkaufspreis:\nBenötigt Wilder Truthahn , Honig (2), Herbstliche Gewürze"}
